c.description="石化火炬没有周期生产，但可被植物攻击，并和四种脑光墓碑一样作为僵尸出兵点使用；地面或水面放置，水上自动携带鸭子救生圈并浮在水面。横纵 2.5 格内的敌方豌豆会被点燃成火豆，寒冰豌豆会被转化为普通豌豆（同一根只转化一次，经过另一根可继续点燃）。范围内的僵尸豌豆同样被点燃，植物方蓝火秘籍或僵尸方暴怒秘籍下为蓝火。每生效一次（消解冰豆，或点燃豌豆、原始豌豆、三向豌豆、僵尸豌豆各一颗）获得15脑光；已点燃的弹不再计数。每座石化火炬累计获得150脑光后进入36秒休眠（死斗期间24秒）：休眠期间不点燃、不转化、不产脑光，仍可被攻击并作为出兵点；醒来后重新累计。";
